def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_sq(x):
    """Calculates tau(x^2), the number of divisors of x squared."""
    if x == 1:
        return 1

    factors = prime_factorization(x)
    tau = 1
    for exponent in factors.values():
        # If x = p^a * ..., then x^2 = p^(2a) * ...
        # The contribution to tau(x^2) is (2a + 1)
        tau *= (2 * exponent + 1)
    return tau

# Brute-force search for x from 1 to 50
max_tau = 0
x_at_max = 0

for x in range(1, 51):
    current_tau = tau_sq(x)
    if current_tau > max_tau:
        max_tau = current_tau
        x_at_max = x

print(f"Maximum tau(x^2) found: {max_tau}")
print(f"Achieved at x = {x_at_max}")

